    public static bool TryConvert(string typeString, out ERewardType rewardType)
    {
        // Normalize the string: "infinite_lives" -> "InfiniteLives"
        if (string.IsNullOrWhiteSpace(typeString))
        {
            rewardType = default;
            return false;
        }
        string normalized = SnakeToPascalCase(typeString);
        return Enum.TryParse(normalized, ignoreCase: true, out rewardType);
    }

    private static string SnakeToPascalCase(string input)
    {
        // Split by underscore and capitalize each word (case-insensitive)
        var parts = input.Split('_');
        for (int i = 0; i < parts.Length; i++)
        {
            var part = parts[i];
            if (string.IsNullOrEmpty(part)) continue;
            part = part.ToLowerInvariant();
            parts[i] = char.ToUpperInvariant(part[0]) + part.Substring(1);
        }
        return string.Join("", parts); // Join without spaces for PascalCase
    }
